// StartButton (StartButton.hpp)
static void bind_StartButton(bb::StartButton* s, const eng::JsonValue& f, eng::BindCtx& ctx) {
  // Unity serializes enum fields as ints: 0 = Story, 1 = Endless. Skipping this made the
  // endless-mode button write the "story" pref -> every run showed "0/7 Notebooks".
  int currentMode = static_cast<int>(s->currentMode);
  ctx.bindInt(f, "currentMode", currentMode);
  s->currentMode = static_cast<bb::StartButton::Mode>(currentMode);
  ctx.bindString(f, "LoadScene", s->LoadScene);
}

